/// One check-to-audit correspondence.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct LighthouseEntry {
    /// Registry check id.
    pub check_id: &'static str,
    /// Lighthouse audit id.
    pub audit_id: &'static str,
    /// Public documentation URL.
    pub doc_url: &'static str,
    /// How the check relates to the audit.
    pub note: &'static str,
}

/// Check-to-audit map in declaration order.
